css:
.row {
  display: flex;
  gap: 12px;
  width: 280px;
  margin: 16px;
  padding: 10px 12px;
  border: 1px solid #d4d4d8;
  border-radius: 6px;
  font-family: system-ui, sans-serif;
}

.name {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.date {
  color: #71717a;
}
